import assert from 'node:assert/strict';
import { Session } from './src/session.js';

const flush = () => Promise.resolve().then(() => Promise.resolve());

// A fresh offline initial attempt is retired on its final unsubscribe.
let calls = 0;
let session = new Session({queryFn(){ calls++; return 'stop'; },timers:{schedule(){}}}, {online:false});
let handle = session.subscribe('central');
assert.equal(session.snapshot('central').fetchStatus, 'paused');
session.unsubscribe(handle);
assert.deepEqual(session.snapshot('central'), {status:'pending', fetchStatus:'idle', data:null});
session.online(true);
await flush();
assert.equal(calls, 0);

// An already-queued resume is also stopped before it can invoke the query.
calls = 0;
session = new Session({queryFn(){ calls++; return 'stop'; },timers:{schedule(){}}}, {online:false});
handle = session.subscribe('harbor');
session.online(true);
session.unsubscribe(handle);
await flush();
assert.equal(calls, 0);
assert.equal(session.snapshot('harbor').fetchStatus, 'idle');

// Re-observing starts a fresh attempt under the normal rules.
handle = session.subscribe('harbor');
await flush();
assert.equal(calls, 1);

// Started work that has not consumed cancellation still completes after unmount.
let resolve;
session = new Session({queryFn(){ return new Promise(r => { resolve = r; }); },timers:{schedule(){}}});
handle = session.subscribe('museum');
session.unsubscribe(handle);
resolve('arriving');
await flush();
assert.deepEqual(session.snapshot('museum'), {status:'success', fetchStatus:'idle', data:'arriving'});

// One observer leaving does not disturb a shared paused attempt.
calls = 0;
session = new Session({queryFn(){ calls++; return 'shared'; },timers:{schedule(){}}}, {online:false});
const first = session.subscribe('union');
const second = session.subscribe('union');
session.unsubscribe(first);
session.online(true);
await flush();
assert.equal(calls, 1);
session.unsubscribe(second);
console.log('lifecycle assertions passed');
